# pip install openai==2.38.0
import os
from openai import OpenAI

client = OpenAI(
    api_key=os.environ["OPEN_API_KEY"],
    base_url=os.environ["GHYAI_BASE_URL"].rstrip("/") + "/v1",
)
model = os.environ["GHYAI_MODEL"]

import json

result = client.chat.completions.create(
    model=model,
    messages=[{"role": "user", "content": "请用 JSON 返回城市名称。"}],
    response_format={"type": "json_schema", "json_schema": {
        "name": "city", "strict": True, "schema": {
            "type": "object", "properties": {"city": {"type": "string"}},
            "required": ["city"], "additionalProperties": False,
        },
    }},
)
choice = result.choices[0]
if choice.finish_reason != "stop" or choice.message.refusal:
    raise RuntimeError("结果未正常完成或被拒绝")
print(json.loads(choice.message.content or ""))

