// npm install openai@7.1.0
import OpenAI from "openai";

import fs from "node:fs";

const base = process.env.GHYAI_BASE_URL;
const client = new OpenAI({
  apiKey: process.env.OPEN_API_KEY,
  baseURL: `${base.replace(/\/$/, "")}/v1`,
});
const model = process.env.GHYAI_MODEL;

const result = await client.audio.speech.create({
  model, voice: process.env.GHYAI_VOICE, input: "你好",
  response_format: "wav", stream_format: "audio",
}, { headers: { "Idempotency-Key": process.env.GHYAI_IDEMPOTENCY_KEY } });
if (!result.body) throw new Error("音频响应为空");
for await (const chunk of result.body) {
  process.stdout.write(Buffer.from(chunk));
}

